import { copyFileSync, existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { readJson, writeText } from "./fs.js";
const MANAGED_NOTICE = "<!-- Generated by AI Deck Kit. Refresh with `aideck guidance sync`. -->";
export function templateSchemaGuidance(manifest) {
    return `# ${manifest.displayName} Schema Guidance

${MANAGED_NOTICE}

This template consumes content schema \`${manifest.contentSchemaVersion}\`.
Treat \`template-manifest.json\` as the version authority.

## Template contract

- Template set: \`${manifest.name}\`
- Template version: \`${manifest.templateVersion}\`
- Content schema: \`${manifest.contentSchemaVersion}\`
- Slide type catalog: \`${manifest.slideTypeCatalog}\`
- Block catalog: \`${manifest.blockCatalog ?? "v1"}\`

Before authoring or changing a deck:

1. Select only a type in \`supportedSlideTypes\`.
2. Read \`layouts/specs/layout-contracts.md\` when present, then read the
   matching layout component for the exact fields it consumes.
3. Do not invent aliases, positional mappings, or substitute icon names.
4. Preserve speaker notes and review annotations in \`content.md\`.

The engine contract is \`engine/schemas/content-schema-guidance.md\`. Use the
\`content-schema-migration\` skill for an explicit schema migration; never
change only a version field or use retemplate as a migration substitute.
`;
}
export function deckSchemaGuidance(manifest) {
    return `# Deck Schema Guidance

${MANAGED_NOTICE}

This deck uses content schema \`${manifest.contentSchemaVersion}\`. Read this
file together with \`deck.json\` and the embedded template guidance before
editing \`content.md\`.

## Template binding

- Template set: \`${manifest.template.set}\`
- Template version: \`${manifest.template.version}\`
- Embedded snapshot: \`template/\`
- Slide type catalog: \`${manifest.slideTypeCatalog}\`
- Block catalog: \`${manifest.blockCatalog}\`

The embedded \`template/template-manifest.json\` is the authority for the
snapshot's fields and layout contracts. Keep \`content.md\` compatible with
the declared \`contentSchemaVersion\`; do not invent aliases, positional
mappings, or substitute icon names.

Schema migration is explicit and user-controlled. Use the
\`content-schema-migration\` skill for a deliberate v1-to-v2 migration; never
change only \`contentSchemaVersion\`, retemplate, or run \`aideck upgrade\` as
a substitute. \`aideck upgrade\` does not rewrite this deck, its content, or
its embedded template snapshot.
`;
}
export function writeTemplateSchemaGuidance(root, manifest) {
    writeGuidance(join(root, "schema-guidance.md"), templateSchemaGuidance(manifest));
}
export function writeDeckSchemaGuidance(root, manifest) {
    writeGuidance(join(root, "schema-guidance.md"), deckSchemaGuidance(manifest));
}
export function inspectSchemaGuidance(workspace, selection) {
    const entries = [];
    const enginePath = join(workspace.engineRoot, "schemas", "content-schema-guidance.md");
    entries.push({ level: "engine", label: "engine", path: enginePath, state: existsSync(enginePath) ? "current" : "missing" });
    const templatesRoot = join(workspace.root, "templates");
    if (selection?.level !== "deck" && existsSync(templatesRoot)) {
        for (const entry of readdirSync(templatesRoot, { withFileTypes: true })) {
            if (!entry.isDirectory() || !entry.name.endsWith(".template"))
                continue;
            if (selection && entry.name !== selection.name.replace(/\.template$/, "") + ".template")
                continue;
            const root = join(templatesRoot, entry.name);
            const manifestPath = join(root, "template-manifest.json");
            if (!existsSync(manifestPath))
                continue;
            const manifest = readJson(manifestPath);
            entries.push(guidanceEntry("template", entry.name, join(root, "schema-guidance.md"), templateSchemaGuidance(manifest)));
        }
    }
    if (selection?.level !== "template" && existsSync(workspace.decksRoot)) {
        for (const entry of readdirSync(workspace.decksRoot, { withFileTypes: true })) {
            if (!entry.isDirectory() || !entry.name.endsWith(".deck"))
                continue;
            if (selection && entry.name !== selection.name.replace(/\.deck$/, "") + ".deck")
                continue;
            const root = join(workspace.decksRoot, entry.name);
            const manifestPath = join(root, "deck.json");
            if (!existsSync(manifestPath))
                continue;
            const manifest = readJson(manifestPath);
            entries.push(guidanceEntry("deck", entry.name, join(root, "schema-guidance.md"), deckSchemaGuidance(manifest)));
        }
    }
    if (selection && entries.length === 1)
        throw new Error(`No project ${selection.level} found: ${selection.name}. Shipped templates are engine-owned.`);
    return entries;
}
export function syncSchemaGuidance(workspace, selection) {
    const before = inspectSchemaGuidance(workspace, selection);
    for (const entry of before) {
        if (entry.level === "engine" || entry.state === "current")
            continue;
        const root = join(entry.path, "..");
        if (entry.level === "template") {
            writeTemplateSchemaGuidance(root, readJson(join(root, "template-manifest.json")));
        }
        else {
            writeDeckSchemaGuidance(root, readJson(join(root, "deck.json")));
        }
    }
    return inspectSchemaGuidance(workspace, selection);
}
function writeGuidance(path, expected) {
    if (existsSync(path)) {
        if (readFileSync(path, "utf8") === expected)
            return;
        let backup = `${path}.backup`;
        let index = 1;
        while (existsSync(backup))
            backup = `${path}.backup-${index++}`;
        copyFileSync(path, backup);
    }
    writeText(path, expected);
}
function guidanceEntry(level, label, path, expected) {
    if (!existsSync(path))
        return { level, label, path, state: "missing" };
    return { level, label, path, state: readFileSync(path, "utf8") === expected ? "current" : "stale" };
}
